-- Frozen accepted feature 006 graph and replacement capacity DDL.
CREATE TABLE task_graphs(sequence INTEGER PRIMARY KEY CHECK(typeof(sequence)='integer' AND sequence>=1),id TEXT UNIQUE NOT NULL,root_task_id TEXT UNIQUE NOT NULL REFERENCES tasks(id),project_id TEXT NOT NULL REFERENCES projects(id),graph_version INTEGER NOT NULL CHECK(typeof(graph_version)='integer' AND graph_version>=1),control_revision INTEGER NOT NULL CHECK(typeof(control_revision)='integer' AND control_revision>=1),state_revision INTEGER NOT NULL CHECK(typeof(state_revision)='integer' AND state_revision>=1),budget_epoch INTEGER NOT NULL CHECK(typeof(budget_epoch)='integer' AND budget_epoch>=1),max_parallelism INTEGER NOT NULL CHECK(max_parallelism IN (1,2)),state TEXT NOT NULL CHECK(state IN ('preparing','queued','running','blocked','cancelling','cancelled','failed','interrupted','completed')),root_input_id TEXT REFERENCES graph_inputs(id),final_node_id TEXT REFERENCES graph_nodes(id),dispatch_owner_instance_id TEXT,dispatch_generation INTEGER NOT NULL CHECK(typeof(dispatch_generation)='integer' AND dispatch_generation>=1),dispatch_data TEXT,data TEXT NOT NULL);
CREATE INDEX task_graphs_project ON task_graphs(project_id,sequence);
CREATE TABLE graph_versions(graph_id TEXT NOT NULL REFERENCES task_graphs(id),version INTEGER NOT NULL CHECK(typeof(version)='integer' AND version>=1),request_id TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(graph_id,version));
CREATE TABLE graph_nodes(id TEXT PRIMARY KEY,graph_id TEXT NOT NULL REFERENCES task_graphs(id),node_key TEXT NOT NULL,task_id TEXT UNIQUE NOT NULL REFERENCES tasks(id),ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal>=1 AND ordinal<=16),control_revision INTEGER NOT NULL CHECK(typeof(control_revision)='integer' AND control_revision>=1),state_revision INTEGER NOT NULL CHECK(typeof(state_revision)='integer' AND state_revision>=1),native_debits INTEGER NOT NULL CHECK(typeof(native_debits)='integer' AND native_debits>=0),automatic_debits INTEGER NOT NULL CHECK(typeof(automatic_debits)='integer' AND automatic_debits>=0 AND automatic_debits<=native_debits),current_input_id TEXT REFERENCES graph_inputs(id),node_admission_id TEXT REFERENCES graph_dispatches(id),state TEXT NOT NULL CHECK(state IN ('waiting','ready','preparing','queued','running','blocked','cancelling','cancelled','failed','interrupted','completed')),data TEXT NOT NULL,UNIQUE(graph_id,node_key),UNIQUE(graph_id,ordinal));
CREATE TABLE graph_inputs(sequence INTEGER PRIMARY KEY CHECK(typeof(sequence)='integer' AND sequence>=1),id TEXT UNIQUE NOT NULL,graph_id TEXT NOT NULL REFERENCES task_graphs(id),graph_version INTEGER NOT NULL CHECK(typeof(graph_version)='integer' AND graph_version>=1),node_id TEXT REFERENCES graph_nodes(id),operation_attempt_id TEXT UNIQUE NOT NULL REFERENCES attempts(id),root_input_id TEXT REFERENCES graph_inputs(id),kind TEXT NOT NULL CHECK(kind IN ('root_basis','node_input')),state TEXT NOT NULL CHECK(state IN ('preparing','ready','blocked','conflicted','incomplete','uncertain','interrupted')),manifest_artifact_id TEXT REFERENCES artifacts(id),index_artifact_id TEXT REFERENCES artifacts(id),staged_blobs_artifact_id TEXT REFERENCES artifacts(id),provenance_artifact_id TEXT REFERENCES artifacts(id),context_artifact_id TEXT REFERENCES artifacts(id),conditions_artifact_id TEXT REFERENCES artifacts(id),source_snapshot_id TEXT REFERENCES source_snapshots(id),data TEXT NOT NULL,FOREIGN KEY(graph_id,graph_version) REFERENCES graph_versions(graph_id,version));
CREATE INDEX graph_inputs_graph ON graph_inputs(graph_id,sequence);
CREATE TABLE graph_dispatches(sequence INTEGER PRIMARY KEY CHECK(typeof(sequence)='integer' AND sequence>=1),id TEXT UNIQUE NOT NULL,graph_id TEXT NOT NULL REFERENCES task_graphs(id),graph_version INTEGER NOT NULL CHECK(typeof(graph_version)='integer' AND graph_version>=1),node_id TEXT NOT NULL REFERENCES graph_nodes(id),task_id TEXT NOT NULL REFERENCES tasks(id),task_version INTEGER NOT NULL CHECK(typeof(task_version)='integer' AND task_version>=1),input_id TEXT NOT NULL REFERENCES graph_inputs(id),attempt_id TEXT UNIQUE NOT NULL REFERENCES attempts(id),workflow_id TEXT NOT NULL REFERENCES workflows(id),step_id TEXT UNIQUE NOT NULL REFERENCES workflow_steps(id),node_admission_id TEXT NOT NULL REFERENCES graph_dispatches(id),logical_slot TEXT NOT NULL,execution_ordinal INTEGER NOT NULL CHECK(typeof(execution_ordinal)='integer' AND execution_ordinal>=1),owner_instance_id TEXT NOT NULL,graph_control_revision INTEGER NOT NULL CHECK(typeof(graph_control_revision)='integer' AND graph_control_revision>=1),node_control_revision INTEGER NOT NULL CHECK(typeof(node_control_revision)='integer' AND node_control_revision>=1),budget_epoch INTEGER NOT NULL CHECK(typeof(budget_epoch)='integer' AND budget_epoch>=1),window_number INTEGER NOT NULL CHECK(typeof(window_number)='integer' AND window_number>=1),fresh_trigger_id TEXT NOT NULL,consumption_key TEXT UNIQUE NOT NULL,native_consumption_key TEXT UNIQUE REFERENCES attempts(id),materialization_artifact_id TEXT REFERENCES artifacts(id),source_snapshot_id TEXT REFERENCES source_snapshots(id),materialization_private_data TEXT,output_data TEXT,known_first_go_at TEXT,known_first_go_attempt_id TEXT REFERENCES attempts(id),data TEXT NOT NULL,FOREIGN KEY(graph_id,graph_version) REFERENCES graph_versions(graph_id,version),FOREIGN KEY(task_id,task_version) REFERENCES task_versions(task_id,version),UNIQUE(node_id,task_version,input_id,logical_slot,execution_ordinal));
CREATE INDEX graph_dispatches_graph ON graph_dispatches(graph_id,sequence);
CREATE INDEX graph_dispatches_node ON graph_dispatches(node_id,sequence);
CREATE TABLE graph_admission_observations(sequence INTEGER PRIMARY KEY CHECK(typeof(sequence)='integer' AND sequence>=1),id TEXT UNIQUE NOT NULL,graph_id TEXT NOT NULL REFERENCES task_graphs(id),node_id TEXT NOT NULL REFERENCES graph_nodes(id),task_version INTEGER NOT NULL CHECK(typeof(task_version)='integer' AND task_version>=1),input_id TEXT NOT NULL REFERENCES graph_inputs(id),consumption_key TEXT UNIQUE NOT NULL,dispatch_id TEXT REFERENCES graph_dispatches(id),outcome TEXT NOT NULL CHECK(outcome IN ('admitted','capacity_wait','blocked')),data TEXT NOT NULL);
CREATE INDEX graph_admission_observations_node ON graph_admission_observations(node_id,sequence);
CREATE TABLE graph_delivery_bindings(operation_id TEXT PRIMARY KEY REFERENCES delivery_operations(id),binding_artifact_id TEXT NOT NULL REFERENCES artifacts(id),data TEXT NOT NULL);
CREATE TABLE capacity_claims(slot INTEGER PRIMARY KEY CHECK(typeof(slot)='integer' AND slot IN (1,2)),attempt_id TEXT UNIQUE NOT NULL REFERENCES attempts(id),owner_instance_id TEXT NOT NULL,context_id TEXT UNIQUE REFERENCES routing_contexts(id),captured_account_id TEXT UNIQUE REFERENCES routing_accounts(id),captured_link_revision INTEGER CHECK(captured_link_revision IS NULL OR (typeof(captured_link_revision)='integer' AND captured_link_revision>=1)),graph_id TEXT REFERENCES task_graphs(id),legacy_barrier INTEGER NOT NULL CHECK(legacy_barrier IN (0,1)),data TEXT NOT NULL,CHECK((captured_account_id IS NULL AND captured_link_revision IS NULL) OR (captured_account_id IS NOT NULL AND captured_link_revision IS NOT NULL)));
